; far.asm -- chapter 48: a routine in a bank switched off
; generated by gen48.py
        INCLUDE "msx.inc"
        OUTPUT "far.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
stat    EQU VARS                ; the status isr read
ticks   EQU VARS + 1            ; frames counted by isr, two bytes
held    EQU VARS + 3            ; the keys of the frame: a 0 for each held
dleft   EQU VARS + 4            ; the frames left of the demo's pair
dnext   EQU VARS + 5            ; the demo's next pair, two bytes
copy    EQU VARS + $20          ; the sprites' attributes: Y, X, pattern, colour
SAT     EQU $1B00               ; the sprites' attributes in the VRAM
SPAT    EQU $3800               ; and their patterns
shift   EQU VARS + 9            ; the pixels on, 0 to 7
table   EQU VARS + 10           ; the name table shown: $18 or $1C
wbank   EQU VARS + 11           ; the next window to write: its bank,
wseg    EQU VARS + 12           ; its segment in the bank,
woff    EQU VARS + 13           ; and its column in the segment
pending EQU VARS + 14           ; the bank of the window last written
shown   EQU VARS + 15           ; the bank of the window shown
fresh   EQU VARS + 16           ; 1 when shown has just changed: its colours to send
SSLOT   EQU $FFFF               ; the secondary slot register, in page 3
BANK2   EQU $77FF             ; page 2's bank is written here (ASCII16)
BSHOW   EQU $B700             ; every bank's bshow
PMAP    EQU $80                 ; the first page of every bank's segments
SEGS    EQU 5                   ; segments a bank
SEGW    EQU 224                 ; columns a segment
BANKS   EQU 7                   ; banks of the world: 1 to 7
X_MIN   EQU 16                  ; the ship's X
X_MAX   EQU 160
Y_MIN   EQU 39                  ; its Y, a line above its top
Y_MAX   EQU 119
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
; WHERE IT BREAKS. long.asm with sends calling bshow without mapping the bank
; of the window shown: the bank in page 2 is the one window last mapped.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $9F          ; colours  $2000, one set for three thirds
        VDP_REG 4, $00          ; shapes   $0000, one set for three thirds
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $01          ; the border
        VRAM_WRITE SAT          ; no sprites yet
        ld a, $D0
        out (VDP_DATA), a
        ld hl, VARS             ; the variables' page, all 0
        ld de, VARS + 1
        ld bc, 255
        ld (hl), 0
        ldir
        ld a, 1
        ld (dleft), a           ; the demo's first pair at the first frame
        ld hl, demo
        ld (dnext), hl
        ld hl, first            ; the sprite's attributes at the start
        ld de, copy
        ld bc, 5
        ldir
        call here               ; page 1's slot: the cartridge
        call setpage2           ; page 2 shows it too
        VRAM_WRITE $0000        ; pattern 0, the sky
        ld c, VDP_DATA
        xor a
        ld b, 8
.sky:   out (c), a
        djnz .sky
        VRAM_WRITE $2000        ; and its colours
        ld a, $11
        ld b, 8
.skyc:  out (c), a
        djnz .skyc
        VRAM_WRITE $1800        ; both name tables all sky
        call sky
        VRAM_WRITE $1C00
        call sky
; the first two windows, the bank shown, and its pairs
        ld a, 1
        ld (wbank), a           ; the first window's place
        ld a, 4
        ld (wseg), a
        ld a, 200
        ld (woff), a
        ld a, $1C
        ld (table), a
        call window             ; the first, into the table not shown: $1800
        ld a, (pending)
        ld (shown), a           ; its bank, shown
        ld a, $18
        ld (table), a
        call window             ; the second, into $1C00: $1800 will be shown
        ld a, 1
        ld (fresh), a           ; the shown bank's colours, and its pairs
        ld a, (shown)
        ld (BANK2), a
        call BSHOW              ; at shift 0
        ld a, 1
        ld (shift), a           ; the first frame: a pixel on
        VRAM_WRITE SPAT         ; the ship's patterns
        ld hl, sprite
        ld bc, 32 << 8 | VDP_DATA
        otir
        jp on

; sky: 768 names of the sky, 0, to the VRAM, with the display off
sky:    ld de, 768
.name:  xor a
        out (VDP_DATA), a
        dec de
        ld a, d
        or e
        jr nz, .name
        ret
on:     ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        in a, (VDP_CTRL)        ; no signal left over
        VDP_REG 1, $E2          ; display on, the frame's signal
main:   ei
frame:  halt                    ; isr: the status kept, the frame counted
woke:   call sends              ; 18  what the beam must not catch
sent:   call run                ; 18  the frame's work
ran:    jr frame                ; 13

; isr: every frame. The status kept in stat, the signal let down; the frame
; counted. Keeps AF, HL
isr:    push af                 ; 12
        in a, (VDP_CTRL)        ; 12  the status: F, 5S, C, a sprite's number
        ld (stat), a            ; 14
        push hl                 ; 12
        ld hl, (ticks)          ; 17
        inc hl                  ;  7
        ld (ticks), hl          ; 17
        pop hl                  ; 11
        pop af                  ; 11
isrend: ei                      ;  5
        ret                     ; 11

; pad: the demo's keys for this frame -> A and held, as chapter 43's input
;      gives them, a 0 for each key held. The demo is pairs of bytes, frames
;      and keys, with a 0 at its end, after which it starts again. Uses A, HL
pad:    ld hl, dleft            ; 11
        dec (hl)                ; 12  a frame fewer of these keys
        jr nz, .same            ; 13, or 8
        ld hl, (dnext)          ; 17  none left: the next pair
        ld a, (hl)              ;  8  its frames
        or a                    ;  5
        jr nz, .pair            ; 13, or 8
        ld hl, demo             ; 11  the end: the first pair again
        ld a, (hl)              ;  8
.pair:  ld (dleft), a           ; 14
        inc hl                  ;  7
        ld a, (hl)              ;  8  its keys
        ld (held), a            ; 14
        inc hl                  ;  7
        ld (dnext), hl          ; 17
        ret                     ; 11
.same:  ld a, (held)            ; 14  the same keys as before
        ret                     ; 11

; sends: straight after HALT, before the paper: the ship's attributes; at a
;        turn, the bank of the window now shown; that bank in page 2, and its
;        bshow: its pairs at the new shift, and its colours if it is new; at a
;        turn, R#2 to the other table. Uses A, BC, HL
sends:  VRAM_WRITE SAT          ; 40
        ld hl, copy             ; 11
        ld bc, 5 << 8 | VDP_DATA ; 11  the ship and the end
        otir                    ; 23 a byte, 18 the last
        ld a, (shift)           ; 14
        or a                    ;  5
        jr nz, .pairs           ; 13, or 8
        ld hl, shown            ; 11  a turn: the bank shown is now
        ld a, (pending)         ; 14  the bank of the window written last
        cp (hl)                 ;  8
        ld (hl), a              ;  8
        ld a, 0                 ;  8  LD, not XOR: the flags are CP's
        jr z, .same             ; 13, or 8
        inc a                   ;  5  a new bank: its colours too
.same:  ld (fresh), a           ; 14
.pairs: call BSHOW              ; 18  the routine of the bank in page 2
        ld a, (shift)           ; 14
        or a                    ;  5
        ret nz                  ; 12, or 6  seven frames in eight, no more
        ld a, (table)           ; 14
        xor $18 ^ $1C           ;  8  the other table: the next window
        ld (table), a           ; 14
        rrca                    ;  5
        rrca                    ;  5  $06 or $07, R#2's
        out (VDP_CTRL), a       ; 12
        ld a, $80 | 2           ;  8
        out (VDP_CTRL), a       ; 12
        ret                     ; 11

; run: the frame's work: the demo's keys, the ship steered, the scroll.
;      Uses every register
run:    call pad                ; 18  A: the keys
        call steer              ; 18
                                ;     on into step

; step: after a turn, the next window's names into the other table; then a
;       pixel on. Uses every register
step:   ld a, (shift)           ; 14
        or a                    ;  5
        call z, window          ; 18, or 11
.on:    ld a, (shift)           ; 14
        inc a                   ;  5
        and 7                   ;  8
        ld (shift), a           ; 14
        ret                     ; 11

; steer: A = the keys -> the ship two pixels up, down, left or right for each
;        key held, kept in the sky. Uses A, B, HL
steer:  ld b, a                 ;  5
        ld hl, copy             ; 11  the ship's Y
        bit 0, b                ; 10  UP?
        jr nz, .down            ; 13, or 8
        ld a, (hl)              ;  8
        cp Y_MIN + 1            ;  8
        jr c, .down             ; 13, or 8  at the top
        sub 2                   ;  8
        ld (hl), a              ;  8
.down:  bit 1, b                ; 10  DOWN?
        jr nz, .left            ; 13, or 8
        ld a, (hl)              ;  8
        cp Y_MAX                ;  8
        jr nc, .left            ; 13, or 8  at the bottom
        add a, 2                ;  8
        ld (hl), a              ;  8
.left:  inc hl                  ;  7  its X
        bit 2, b                ; 10  LEFT?
        jr nz, .right           ; 13, or 8
        ld a, (hl)              ;  8
        cp X_MIN + 1            ;  8
        jr c, .right            ; 13, or 8  at the left
        sub 2                   ;  8
        ld (hl), a              ;  8
.right: bit 3, b                ; 10  RIGHT?
        ret nz                  ; 12, or 6
        ld a, (hl)              ;  8
        cp X_MAX                ;  8
        ret nc                  ; 12, or 6  at the right
        add a, 2                ;  8
        ld (hl), a              ;  8
        ret                     ; 11


; window: the next window, its bank wbank, its segment wseg, its column woff,
;         into the name table not shown: its bank in page 2, then rows 1 to
;         4 and 17 to 23, each row's pairs in a page of the segment's 11; then
;         the place of the window after it. Uses A, BC, DE, HL
window: ld a, (wbank)           ; 14
        ld (pending), a         ; 14  the bank of the window written
        ld (BANK2), a           ; 14  page 2 shows it
        ld a, (wseg)            ; 14
        ld b, a                 ;  5
        add a, a                ;  5
        ld c, a                 ;  5  2 x the segment
        add a, a                ;  5
        add a, a                ;  5
        add a, c                ;  5
        add a, b                ;  5  11 x the segment
        add a, PMAP             ;  8
        ld h, a                 ;  5  its first page
        ld a, (woff)            ; 14
        ld e, a                 ;  5  E: the column
        ld l, a                 ;  5  HL: row 1's pair there
        ld a, (table)           ; 14
        xor $18 ^ $1C           ;  8  the table not shown
        ld d, a                 ;  5  D: its high byte
        ld a, 32                ;  8
        out (VDP_CTRL), a       ; 12
        ld a, d                 ;  5
        or $40                  ;  8
        out (VDP_CTRL), a       ; 12  its row 1, for writing
        ld c, 4                 ;  8  four rows
        call names              ; 18
        ld a, low (32 * 17)     ;  8
        out (VDP_CTRL), a       ; 12
        ld a, d                 ;  5
        or high (32 * 17) | $40 ;  8
        out (VDP_CTRL), a       ; 12  its row 17
        ld c, 7                 ;  8  seven rows
        call names              ; 18
        ld hl, woff             ; 11  the next window: a column on,
        inc (hl)                ; 12
        ld a, (hl)              ;  8
        cp SEGW                 ;  8
        ret c                   ; 12, or 6
        ld (hl), 0              ; 11  or the next segment's first,
        ld hl, wseg             ; 11
        inc (hl)                ; 12
        ld a, (hl)              ;  8
        cp SEGS                 ;  8
        ret c                   ; 12, or 6
        ld (hl), 0              ; 11  or the next bank's,
        ld hl, wbank            ; 11
        inc (hl)                ; 12
        ld a, (hl)              ;  8
        cp BANKS + 1            ;  8
        ret c                   ; 12, or 6
        ld (hl), 1              ; 11  or, past bank 7, bank 1's again
        ret                     ; 11

; names: HL = a row's pair at the column E, C = rows -> C rows of 32 names,
;        one after another in the VRAM, 39 T-states a name. Uses A, BC, HL
names:  ld b, 32                ;  8
.name:  ld a, (hl)              ;  8
        out (VDP_DATA), a       ; 12
        inc l                   ;  5
        djnz .name              ; 14, or 9
        inc h                   ;  5  the next row's page
        ld l, e                 ;  5
        dec c                   ;  5
        jr nz, names            ; 13, or 8
        ret                     ; 11

; here: -> A = the slot ID of page 1, where INIT runs: the primary slot from
; port $A8 and, if EXPTBL says it is expanded, the secondary from the
; slot's own register. The interrupts must be off. Uses A, BC, HL
here:   in a, (PPI_A)           ; 12
        rrca                    ;  5
        rrca                    ;  5
        and 3                   ;  8  page 1's primary slot
        ld c, a                 ;  5
        ld b, 0                 ;  8
        ld hl, EXPTBL           ; 11
        add hl, bc              ; 12
        or (hl)                 ;  8  bit 7 if the slot is expanded
        ret p                   ; 12, or 6  it is not: that is the ID
        ld l, a                 ;  5  1000 00PP
        and 3                   ;  8
        call subreg             ; 18  the slot's register
        and %00001100           ;  8  page 1's secondary slot
        or l                    ;  5
        ret                     ; 11

; setpage2: A = a slot ID -> page 2 shows that slot: its primary slot in
; port $A8 and, for an expanded slot, its secondary slot in the slot's
; register, written at $FFFF through page 3 and copied into SLTTBL for the
; BIOS. The interrupts must be off. Uses A, BC, DE, HL
setpage2: ld e, a               ;  5  the slot ID
        and 3                   ;  8
        rrca                    ;  5
        rrca                    ;  5
        ld d, a                 ;  5  the primary slot in bits 6-7
        rrca                    ;  5
        rrca                    ;  5
        ld b, a                 ;  5  and in bits 4-5
        in a, (PPI_A)           ; 12
        ld c, a                 ;  5  the slots as they are
        bit 7, e                ; 10  expanded?
        jr z, .primary          ; 13, or 8
        and $3F                 ;  8
        or d                    ;  5
        out (PPI_A), a          ; 12  page 3 shows the slot: no RAM
        ld a, (SSLOT)           ; 14
        cpl                     ;  5  its register, as it stands
        and %11001111           ;  8  page 2's secondary slot cleared
        ld d, a                 ;  5
        ld a, e                 ;  5
        and %00001100           ;  8  the new one, in bits 2-3
        rlca                    ;  5
        rlca                    ;  5  and in bits 4-5
        or d                    ;  5
        ld (SSLOT), a           ; 14  written
        ld d, a                 ;  5
        ld a, c                 ;  5
        out (PPI_A), a          ; 12  page 3 back: the RAM again
        ld a, e                 ;  5
        and 3                   ;  8
        add a, low SLTTBL       ;  8
        ld l, a                 ;  5
        ld h, high SLTTBL       ;  8
        ld (hl), d              ;  8  SLTTBL for that slot, as the BIOS keeps it
.primary: ld a, c               ;  5
        and %11001111           ;  8  page 2's primary slot cleared
        or b                    ;  5  and set
        out (PPI_A), a          ; 12
        ret                     ; 11

; subreg: A = an expanded primary slot -> A = its secondary slot register,
; read at $FFFF through page 3, which hands it back complemented. The
; interrupts must be off: while page 3 shows that slot the RAM is gone, and
; the stack with it. Uses A, B, C
subreg: rrca                    ;  5
        rrca                    ;  5  the slot into bits 6-7
        ld b, a                 ;  5
        in a, (PPI_A)           ; 12
        ld c, a                 ;  5  the slots as they are
        and $3F                 ;  8
        or b                    ;  5
        out (PPI_A), a          ; 12  page 3 shows the slot: no RAM
        ld a, (SSLOT)           ; 14  its register, complemented
        cpl                     ;  5
        ld b, a                 ;  5
        ld a, c                 ;  5
        out (PPI_A), a          ; 12  page 3 back: the RAM again
        ld a, b                 ;  5
        ret                     ; 11
first:                          ; the ship's attributes at the start, and the end
        db $4F, $28, $00, $0F, $D0
sprite:                         ; the ship, 16 x 16 (chapter 26)
        db $00, $30, $38, $3C, $1F, $3F, $78, $78
        db $7F, $7F, $3F, $1F, $3C, $38, $30, $00
        db $00, $00, $00, $00, $00, $E0, $FC, $FE
        db $FE, $FC, $E0, $00, $00, $00, $00, $00
; the demo, chapter 47's flight: pairs of frames and keys, a 0 for each key held,
; and a 0 at the end
demo:   db 20, %11110101        ; DOWN RIGHT
        db 12, %11110111        ; RIGHT
        db 20, %11110110        ; UP RIGHT
        db 12, %11111111        ; none
        db 20, %11111010        ; UP LEFT
        db 12, %11111011        ; LEFT
        db 20, %11111001        ; DOWN LEFT
        db 12, %11111111        ; none
        db 20, %11110101        ; DOWN RIGHT
        db 12, %11110111        ; RIGHT
        db 20, %11110110        ; UP RIGHT
        db 12, %11111111        ; none
        db 20, %11111010        ; UP LEFT
        db 12, %11111011        ; LEFT
        db 20, %11111001        ; DOWN LEFT
        db 12, %11111111        ; none
        db 20, %11110101        ; DOWN RIGHT
        db 12, %11110111        ; RIGHT
        db 20, %11110110        ; UP RIGHT
        db 12, %11111111        ; none
        db 20, %11111010        ; UP LEFT
        db 12, %11111011        ; LEFT
        db 20, %11111001        ; DOWN LEFT
        db 12, %11111111        ; none
        db 20, %11110101        ; DOWN RIGHT
        db 12, %11110111        ; RIGHT
        db 20, %11110110        ; UP RIGHT
        db 12, %11111111        ; none
        db 20, %11111010        ; UP LEFT
        db 12, %11111011        ; LEFT
        db 20, %11111001        ; DOWN LEFT
        db 12, %11111111        ; none
        db 0                    ; the end: the first pair again
        ASSERT $ <= $8000, bank 0 is longer than 16 KB
        ds $8000 - $, $FF

; ================================================================ bank 1
        OUTEND
        OUTPUT "far.rom", a  ; bank 1, seen at $8000 when page 2 shows it
        ORG $8000
seg1_0_1:                       ; segment 0, columns 0-223, row 1
        db $01, $02, $02, $03, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04
        db $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $01, $02, $02, $02
        db $02, $02, $02, $03, $04, $04, $04, $04, $01, $02, $02, $03, $04, $04, $04, $04
        db $04, $04, $01, $03, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04
        db $04, $04, $04, $04, $01, $02, $02, $03, $04, $04, $04, $04, $04, $04, $01, $03
        db $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04
        db $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $01, $02, $03
        db $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04
        db $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04
        db $04, $04, $04, $04, $04, $04, $04, $04, $01, $02, $02, $03, $04, $04, $04, $04
        db $04, $04, $04, $04, $04, $04, $01, $03, $04, $04, $04, $04, $04, $04, $04, $04
        db $04, $04, $04, $04, $04, $04, $01, $03, $04, $04, $04, $04, $04, $04, $04, $04
        db $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04
        db $04, $01, $02, $02, $02, $02, $02, $03, $04, $04, $04, $04, $04, $04, $04, $04
        db $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04
        db $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $00
        ; row 2
        db $05, $00, $00, $06, $07, $02, $02, $03, $04, $04, $04, $04, $01, $02, $02, $02
        db $02, $02, $02, $03, $04, $04, $04, $04, $04, $01, $02, $08, $05, $00, $00, $00
        db $00, $00, $00, $06, $07, $02, $02, $08, $05, $00, $00, $06, $09, $04, $04, $04
        db $04, $0A, $05, $06, $07, $02, $02, $03, $04, $04, $04, $04, $04, $01, $02, $02
        db $02, $02, $02, $08, $05, $00, $00, $06, $09, $04, $04, $04, $04, $0A, $05, $06
        db $09, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04
        db $04, $04, $04, $04, $01, $02, $02, $03, $04, $04, $04, $04, $0A, $05, $00, $06
        db $07, $02, $02, $02, $02, $02, $02, $02, $02, $02, $02, $02, $02, $02, $02, $03
        db $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04
        db $04, $01, $02, $02, $02, $02, $02, $08, $05, $00, $00, $06, $07, $02, $02, $03
        db $04, $04, $04, $04, $04, $0A, $05, $06, $09, $04, $04, $04, $04, $04, $04, $04
        db $04, $04, $04, $04, $04, $0A, $05, $06, $09, $04, $04, $04, $04, $04, $04, $04
        db $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04
        db $0A, $05, $00, $00, $00, $00, $00, $06, $09, $04, $04, $04, $01, $02, $02, $03
        db $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04, $04
        db $04, $04, $04, $04, $04, $01, $02, $02, $02, $02, $02, $03, $04, $04, $04, $00
        ; row 3
        db $00, $00, $00, $00, $00, $00, $00, $06, $07, $02, $02, $08, $05, $00, $00, $00
