; bshow, bank 1's: its pairs at the shift, 22 patterns from 1, with OTIR;
; and when fresh says the bank is new, their colours. Uses A, BC, HL
bshow1: VRAM_WRITE $0008        ; 40  pair 1's pattern, the first
        ld a, (shift)           ; 14
        add a, a                ;  5  two bytes a shift
        add a, low stab1        ;  8
        ld l, a                 ;  5
        ld h, high stab1        ;  8  HL: the shift's place in stab
        ld a, (hl)              ;  8
        inc l                   ;  5
        ld h, (hl)              ;  8
        ld l, a                 ;  5  HL: the pairs at this shift
        ld bc, 176 << 8 | VDP_DATA ; 11
        otir                    ; 23 a byte, 18 the last
        ld a, (fresh)           ; 14
        or a                    ;  5
        ret z                   ; 12, or 6  the same bank as before
        xor a                   ;  5
        ld (fresh), a           ; 14  sent once
        VRAM_WRITE $2008        ; 40  pair 1's colours
        ld hl, pcols1           ; 11
        ld b, 176               ;  8
        otir                    ; 23 a byte, 18 the last
        ret                     ; 11
        ALIGN 16
stab1:                          ; where each shift's patterns start
        dw shifts1 + 0
        dw shifts1 + 176
        dw shifts1 + 352
        dw shifts1 + 528
        dw shifts1 + 704
        dw shifts1 + 880
        dw shifts1 + 1056
        dw shifts1 + 1232
