; bshow, bank 4's: its pairs at the shift, 22 patterns from 1, with OTIR;
; and when fresh says the bank is new, their colours. Uses A, BC, HL
bshow4: VRAM_WRITE $0008        ; 40  pair 1's pattern, the first
        ld a, (shift)           ; 14
        add a, a                ;  5  two bytes a shift
        add a, low stab4        ;  8
        ld l, a                 ;  5
        ld h, high stab4        ;  8  HL: the shift's place in stab
        ld a, (hl)              ;  8
        inc l                   ;  5
        ld h, (hl)              ;  8
        ld l, a                 ;  5  HL: the pairs at this shift
        ld bc, 176 << 8 | VDP_DATA ; 11
        otir                    ; 23 a byte, 18 the last
        ld a, (fresh)           ; 14
        or a                    ;  5
        ret z                   ; 12, or 6  the same bank as before
        xor a                   ;  5
        ld (fresh), a           ; 14  sent once
        VRAM_WRITE $2008        ; 40  pair 1's colours
        ld hl, pcols4           ; 11
        ld b, 176               ;  8
        otir                    ; 23 a byte, 18 the last
        ret                     ; 11
        ALIGN 16
stab4:                          ; where each shift's patterns start
        dw shifts4 + 0
        dw shifts4 + 176
        dw shifts4 + 352
        dw shifts4 + 528
        dw shifts4 + 704
        dw shifts4 + 880
        dw shifts4 + 1056
        dw shifts4 + 1232
